def affected(test_tup1, test_tup2) -> bool:
    # The edit changes results only when every zipped pair satisfies x >= y
    # (mutant returns True) but at least one pair has x == y (original returns False).
    try:
        pairs = list(zip(test_tup1, test_tup2))
        return all(x >= y for x, y in pairs) and any(x == y for x, y in pairs)
    except Exception:
        return False
